def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Run scheduled jobs sequentially and return an attempt log."""
    run_log: list[dict] = []

    for job in jobs:
        name = job["name"]
        policy = job["on_error"]["policy"]
        retries = job["on_error"]["retries"]
        attempts = 0

        while True:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": name,
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                if policy == "RETRY" and attempts <= retries:
                    continue

                run_log.append(
                    {
                        "name": name,
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                run_log.append(
                    {
                        "name": name,
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
